contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function testWithdrawRevertsForNonOwner(uint256 _value) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(_value == 0);
        require(c.owner() != address(this));
        require(address(this).balance >= 0);
        bool ok; c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = true; }
        assert(!ok);
    }
}

