// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _testWithdrawRevertsForNonOwner(uint256 _value) internal {
        vm.deal(address(c), VALUE_CAP);
        _value = 0;
        vm.assume(c.owner() != address(this));
        vm.assume(address(this).balance >= 0);
        bool ok;
        try c.withdraw(_value) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }

    function testFuzz_testWithdrawRevertsForNonOwner(uint256 _value) public {
        _testWithdrawRevertsForNonOwner(_value);
    }

    receive() external payable {}
}
